const AVATAR_LIST = Object.values(AVATARS);

const AVATAR_COUNT = AVATAR_LIST.length;

function hashCode(str: string): number {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash |= 0;
  }
  return Math.abs(hash);
}

export function getAvatarXml(seed: string): string {
  const index = hashCode(seed) % AVATAR_COUNT;
  return AVATAR_LIST[index];
}

export function getAvatarByIndex(index: number): string {
  return AVATAR_LIST[Math.abs(index) % AVATAR_COUNT];
}

export function getAllAvatarXmls(): string[] {
  return [...AVATAR_LIST];
}
